/**
 * Post-build step (see the "build" script in package.json). Runs after `vite build` (dist/) and
 * `vite build --ssr` (dist-ssr/):
 *   1. renders the React app to HTML and writes it into dist/index.html, so crawlers and no-JS
 *      visitors get real content (the browser still boots with createRoot: no hydration);
 *   2. injects the schema.org JSON-LD generated by src/seo/structuredData.ts;
 *   3. writes dist/sitemap.xml;
 *   4. removes dist-ssr/.
 * Any problem fails the build, so a broken page can never be deployed silently.
 */
import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const distDir = resolve(root, 'dist')
const ssrDir = resolve(root, 'dist-ssr')
const htmlPath = resolve(distDir, 'index.html')

const ROOT_MARKER = '<div id="root"></div>'
const DATA_MARKER = '<!--app-structured-data-->'

function fail(message) {
  console.error(`\nprerender failed: ${message}`)
  process.exit(1)
}

/** Minimal HTML entity decoding for text lifted out of <title> / attribute values. */
function decodeEntities(text) {
  return text
    .replace(/&#x([\da-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, dec) => String.fromCodePoint(Number(dec)))
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&')
}

/** Value of attribute `name` inside one HTML tag string. */
function attr(tag, name) {
  const match = new RegExp(`\\s${name}\\s*=\\s*(?:"([^"]*)"|'([^']*)')`, 'i').exec(tag)
  return match ? decodeEntities(match[1] ?? match[2]).trim() : ''
}

function findTag(html, pattern) {
  return pattern.exec(html)?.[0] ?? ''
}

/** Date of the last commit (YYYY-MM-DD) for the sitemap's <lastmod>; today (UTC) when git can't tell. */
function lastModified() {
  try {
    const date = execFileSync('git', ['log', '-1', '--format=%cs'], { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim()
    if (/^\d{4}-\d{2}-\d{2}$/.test(date)) return date
  } catch {
    /* no git, or not a checkout */
  }
  return new Date().toISOString().slice(0, 10)
}

async function main() {
  if (!existsSync(htmlPath)) fail('dist/index.html not found. Run `vite build` first.')
  const entry = resolve(ssrDir, 'entry-server.js')
  if (!existsSync(entry)) fail('dist-ssr/entry-server.js not found. Run `vite build --ssr src/entry-server.tsx --outDir dist-ssr` first.')

  const template = readFileSync(htmlPath, 'utf8')
  if (!template.includes(ROOT_MARKER)) fail(`dist/index.html has no ${ROOT_MARKER}`)
  if (!template.includes(DATA_MARKER)) fail(`dist/index.html has no ${DATA_MARKER}`)

  const title = decodeEntities(/<title>([\s\S]*?)<\/title>/i.exec(template)?.[1] ?? '').trim()
  const description = attr(findTag(template, /<meta\s[^>]*name\s*=\s*["']description["'][^>]*>/i), 'content')
  const canonical = attr(findTag(template, /<link\s[^>]*rel\s*=\s*["']canonical["'][^>]*>/i), 'href')
  if (!title) fail('dist/index.html has no <title>')
  if (!description) fail('dist/index.html has no meta description')
  if (!/^https?:\/\//.test(canonical)) fail('dist/index.html has no absolute canonical link')

  const { render, buildStructuredData } = await import(pathToFileURL(entry).href)
  const app = await render()
  if (!app.trim()) fail('the app rendered to empty HTML')
  if (!app.includes('<h1')) fail('the rendered app has no <h1>')
  if (!app.includes('HIZARC')) fail('the rendered app never mentions HIZARC')

  // JSON-LD: escape '<' so the data can never close the <script> element or open a comment.
  const json = JSON.stringify(buildStructuredData({ title, description })).replace(/</g, '\\u003c')
  const script = `<script type="application/ld+json">${json}</script>`

  // Replacer functions, not strings: '$&', '$1' etc. in the content must stay literal.
  const html = template.replace(ROOT_MARKER, () => `<div id="root">${app}</div>`).replace(DATA_MARKER, () => script)
  if (!html.includes('HIZARC')) fail('the final HTML does not mention HIZARC')
  writeFileSync(htmlPath, html)

  // the home page plus the static pages served straight from public/ (game privacy policies)
  const pages = [canonical, ...['/stoneplay/privacy-policy/', '/stoneplay/free/privacy-policy/'].map((path) => new URL(path, canonical).href)]
  const urls = pages.map((loc) => `  <url>
    <loc>${loc}</loc>
    <lastmod>${lastModified()}</lastmod>
  </url>`)
  const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.join('\n')}
</urlset>
`
  writeFileSync(resolve(distDir, 'sitemap.xml'), sitemap)

  rmSync(ssrDir, { recursive: true, force: true })
  console.log(`prerender: injected ${Buffer.byteLength(app)} bytes of HTML + ${Buffer.byteLength(json)} bytes of JSON-LD into dist/index.html, wrote dist/sitemap.xml`)
}

main().catch((error) => fail(error instanceof Error ? (error.stack ?? error.message) : String(error)))
